import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import type { SearchRow, StreamScope } from "@eidolon/retrieval";
import {
  formatChunks,
  formatFacts,
  RECALL_NOTES,
  RENDER_HEADER,
  recallResult,
  renderRecallResult,
  scopeFilter,
} from "../src/index.ts";
import { latestUserText, sameTurn, setBlock, turnKeyOf } from "../src/messages.ts";
import { broadcast, FakeContext, RECALL_HIT, scope } from "./helpers.ts";

// Generated by running stream_archive.py, persona_facts.py and stream_recall.py on these inputs.
const goldens = JSON.parse(
  readFileSync(new URL("./fixtures/goldens.json", import.meta.url), "utf8"),
) as {
  formatChunks: { chunks: SearchRow[]; prefix: string; output: string }[];
  formatFacts: { facts: SearchRow[]; prefix: string; output: string }[];
  scopeFilter: { scope: StreamScope; broadcasts: string[]; where: string | null }[];
  renderResult: { name: string; output: string }[];
};

const ARCHIVE_PROMPT =
  "你过去直播里相关的片段（用来 ground 你的回复，不要照念，也不要把日期念出来）：\n\n";

function rendered(name: string): string {
  return goldens.renderResult.find((r) => r.name === name)?.output as string;
}

describe("formatFacts", () => {
  test("matches persona_facts.py", () => {
    for (const c of goldens.formatFacts) expect(formatFacts(c.facts, c.prefix)).toBe(c.output);
  });

  test("the context spec's golden", () => {
    expect(
      formatFacts(
        [
          { text: " 喜欢奶茶 ", date: "2026-09-01" },
          { text: "", date: "x" },
          { text: "无日期" },
          { text: "空日期", date: "" },
        ],
        "你过去在直播里说过 / 设定过的相关事实（用来 ground 你的回复，不要照念，也不要把日期念出来）：\n\n",
      ),
    ).toBe(
      "你过去在直播里说过 / 设定过的相关事实（用来 ground 你的回复，不要照念，也不要把日期念出来）：\n\n\n- [2026-09-01] 喜欢奶茶\n- 无日期\n- 空日期\n",
    );
  });
});

describe("formatChunks", () => {
  test("matches stream_archive.py", () => {
    for (const c of goldens.formatChunks) expect(formatChunks(c.chunks, c.prefix)).toBe(c.output);
  });

  test("an empty list is the stripped prefix", () => {
    expect(formatChunks([], ARCHIVE_PROMPT)).toBe(
      "你过去直播里相关的片段（用来 ground 你的回复，不要照念，也不要把日期念出来）：\n",
    );
  });
});

describe("scopeFilter", () => {
  test("matches stream_recall.py", () => {
    const B = broadcast("2026-09-08", "BV1abc", 2);
    for (const row of goldens.scopeFilter) {
      const broadcasts = row.broadcasts.map(() => B);
      expect(scopeFilter(scope(row.scope), broadcasts)).toBe(row.where);
    }
  });

  test("quotes ids for LanceDB", () => {
    expect(scopeFilter(scope({ streamIds: ["a'b"] }), [])).toBe("stream_id IN ('a''b')");
    expect(scopeFilter(scope({ latest: 1 }), [broadcast("2026-09-08", "BV1abc", 2)])).toBe(
      "stream_id IN ('2026-09-08-BV1abc_p1', '2026-09-08-BV1abc_p2')",
    );
    expect(scopeFilter(scope({ label: "全部已归档直播" }), [broadcast("2026-09-08")])).toBeNull();
  });
});

describe("renderRecallResult", () => {
  test("an overview without a scope is the header and the note", () => {
    expect(
      renderRecallResult(
        recallResult({ scope: null, overview: true, note: RECALL_NOTES.noScope }),
        ARCHIVE_PROMPT,
      ),
    ).toBe(rendered("no-scope"));
  });

  test("a blank label renders as 指定场次", () => {
    expect(
      renderRecallResult(recallResult({ scope: scope(), overview: false }), ARCHIVE_PROMPT),
    ).toBe(rendered("empty-label"));
    expect(rendered("empty-label")).toBe(`${RENDER_HEADER}\n查询范围：指定场次`);
  });

  test("matches stream_archive.py with broadcasts and chunks", () => {
    const latest = broadcast("2026-09-08", "BV1abc", 2);
    expect(
      renderRecallResult(
        recallResult({
          scope: scope({ latest: 1, label: "最近一次直播" }),
          overview: true,
          broadcasts: [latest],
        }),
        ARCHIVE_PROMPT,
      ),
    ).toBe(rendered("latest-overview"));
    expect(
      renderRecallResult(
        recallResult({
          scope: scope({
            startDate: "2026-09-08",
            endDate: "2026-09-09",
            label: "2026-09-08 至 2026-09-08",
          }),
          overview: false,
          broadcasts: [latest],
          chunks: [RECALL_HIT],
        }),
        ARCHIVE_PROMPT,
      ),
    ).toBe(rendered("date-details"));
  });
});

describe("message helpers", () => {
  test("a turn is the user count and the latest user content", () => {
    const messages: unknown[] = [{ role: "user", content: "a" }];
    const first = turnKeyOf(messages);
    expect(first).toEqual({ userCount: 1, latestContent: "a" });
    expect(sameTurn(null, first)).toBe(false);
    messages.push({ role: "developer", content: "memories" }, { role: "tool", content: "r" });
    messages.push({ llm: "openai", message: { role: "user", content: "x" } });
    expect(sameTurn(first, turnKeyOf(messages))).toBe(true);
    messages.push({ role: "assistant", content: "b" }, { role: "user", content: "a" });
    expect(sameTurn(first, turnKeyOf(messages))).toBe(false);
  });

  test("non-string content keys by its Python repr", () => {
    expect(turnKeyOf([{ role: "user", content: [{ type: "text", text: "hi" }] }])).toEqual({
      userCount: 1,
      latestContent: "[{'type': 'text', 'text': 'hi'}]",
    });
    expect(turnKeyOf([{ role: "user" }]).latestContent).toBe("");
    expect(turnKeyOf([{ role: "user", content: null }]).latestContent).toBe("None");
    expect(turnKeyOf([]).latestContent).toBe("");
  });

  test("latestUserText skips non-string content", () => {
    expect(
      latestUserText([
        { role: "user", content: "  first " },
        { role: "user", content: [{ type: "text", text: "x" }] },
        { role: "assistant", content: "reply" },
      ]),
    ).toBe("  first ");
    expect(latestUserText([{ role: "system", content: "x" }])).toBeNull();
  });

  test("setBlock replaces every matching system block wherever it sits", () => {
    const specific = { llm: "openai", message: { role: "system", content: "P:old" } };
    const context = new FakeContext([
      { role: "system", content: "P:stale" },
      { role: "user", content: "q" },
      specific,
      { role: "user", content: "P:not system" },
      { role: "system", content: ["P:list"] },
      { role: "system", content: "P:again" },
      { role: "system", content: "keep" },
    ]);
    setBlock(context, "P:", "new", 2);
    expect(context.messages).toEqual([
      { role: "user", content: "q" },
      specific,
      { role: "system", content: "P:new" },
      { role: "user", content: "P:not system" },
      { role: "system", content: ["P:list"] },
      { role: "system", content: "keep" },
    ]);
  });

  test("setBlock clamps the position and an empty text only removes", () => {
    const context = new FakeContext([{ role: "user", content: "q" }]);
    setBlock(context, "P:", "x", 2);
    expect(context.contents()).toEqual(["q", "P:x"]);
    let writes = 0;
    const counting = {
      getMessages: () => context.getMessages(),
      setMessages: (messages: unknown[]) => {
        writes++;
        context.setMessages(messages);
      },
      setHiddenTools: () => {},
    };
    setBlock(counting, "P:", "", 2);
    expect(context.contents()).toEqual(["q"]);
    setBlock(counting, "P:", "", 2);
    expect(writes).toBe(2);
  });
});
